package app.roadstr.core.protocol.interop

import app.roadstr.core.protocol.nostr.BoundedJsonParser
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * Runs every vector of docs/interoperability/vectors/road-bridge-v1.json (SPECIFICATION.md 4.2-4.3
 * in jooray/roadbeacon), generated by tools/gen_road_bridge_vectors.py there.
 */
class BridgeSummaryCodecVectorsTest {
    @Suppress("UNCHECKED_CAST")
    private val root: Map<String, Any?> by lazy {
        val stream = requireNotNull(javaClass.getResourceAsStream("/road-bridge-v1.json")) {
            "vectors file is not on the test classpath"
        }
        BoundedJsonParser(stream.bufferedReader(Charsets.UTF_8).use { it.readText() }).parse() as Map<String, Any?>
    }

    @Suppress("UNCHECKED_CAST")
    private fun section(name: String): List<Map<String, Any?>> {
        val rows = root[name] as List<Map<String, Any?>>
        assertTrue("section $name is empty", rows.isNotEmpty())
        return rows
    }

    private fun Map<String, Any?>.int(key: String): Int = (this[key] as Number).toInt()

    private fun Map<String, Any?>.long(key: String): Long = (this[key] as Number).toLong()

    private fun Map<String, Any?>.frame(): ByteArray = unhex(this["frame"] as String)

    private fun Map<String, Any?>.label(): String = this["name"] as String

    @Suppress("UNCHECKED_CAST")
    private fun Map<String, Any?>.map(key: String): Map<String, Any?> = this[key] as Map<String, Any?>

    @Suppress("UNCHECKED_CAST")
    private fun Map<String, Any?>.list(key: String): List<Map<String, Any?>> = this[key] as List<Map<String, Any?>>

    @Test
    fun `duration codes encode and decode as the vectors say`() {
        assertEquals(1L, root["version"])
        for (row in section("duration_encode")) {
            val expected = (row["code"] as Number?)?.toInt()
            assertEquals("${row["seconds"]} s", expected, BridgeSummaryCodec.encodeDuration(row.long("seconds")))
        }
        for (row in section("duration_decode")) {
            val expected = (row["seconds"] as Number?)?.toLong()
            assertEquals("code ${row["code"]}", expected, BridgeSummaryCodec.decodeDuration(row.int("code")))
        }
    }

    @Test
    fun `category lifetimes are the ones the decoder enforces`() {
        val lifetimes = root.map("category_lifetime_s")
        for ((value, seconds) in lifetimes) {
            val type = CompactRoadType.fromValue(value.toInt()) ?: fail("unknown category $value") as Nothing
            assertEquals(type.wireName, (seconds as Number).toLong(), type.effectiveTtlSeconds)
        }
        assertEquals(CompactRoadType.entries.size, lifetimes.size)
    }

    @Test
    fun `valid summaries encode to the exact frame and decode to the exact entries`() {
        for (vector in section("summary_valid")) {
            val point = vector.map("point")
            val entries = vector.list("entries").map {
                BridgeSummaryCodec.Entry(
                    latitudeE6 = it.int("lat_e6"),
                    longitudeE6 = it.int("lon_e6"),
                    category = it.int("category"),
                    ageSeconds = it.long("age_s"),
                    remainingSeconds = it.long("remaining_s"),
                    stillThere = it.int("still"),
                    gone = it.int("gone"),
                )
            }
            when (val encoded = BridgeSummaryCodec.encodeSummary(point.int("lat_e6"), point.int("lon_e6"), entries)) {
                is BridgeSummaryCodec.Result.Ok -> assertEquals(vector.label(), vector["frame"], hex(encoded.value))
                is BridgeSummaryCodec.Result.Failed -> fail("${vector.label()}: ${encoded.error}")
            }
            assertEquals(vector.int("content_bytes"), vector.frame().size)
            val decoded = (BridgeSummaryCodec.decodeSummary(vector.frame()) as BridgeSummaryCodec.Result.Ok).value
            val expected = vector.list("decoded")
            assertEquals(vector.label(), expected.size, decoded.entries.size)
            for ((want, got) in expected.zip(decoded.entries)) {
                assertEquals(want.int("lat_e6"), got.latitudeE6)
                assertEquals(want.int("lon_e6"), got.longitudeE6)
                assertEquals(want.int("category"), got.category)
                assertEquals(want.long("age_s"), got.ageSeconds)
                assertEquals(want.long("remaining_s"), got.remainingSeconds)
                assertEquals(want.int("still"), got.stillThere)
                assertEquals(want.int("gone"), got.gone)
                assertEquals(want["id"], got.id)
            }
        }
    }

    @Test
    fun `invalid summaries are refused with the named error`() {
        for (vector in section("summary_invalid")) {
            val result = BridgeSummaryCodec.decodeSummary(vector.frame())
            assertEquals(vector.label(), BridgeSummaryCodec.Result.Failed(BridgeSummaryCodec.Error.valueOf(vector["error"] as String)), result)
        }
    }

    @Test
    fun `entries that break a rule are dropped and the rest kept`() {
        for (vector in section("summary_entries_dropped")) {
            val decoded = (BridgeSummaryCodec.decodeSummary(vector.frame()) as BridgeSummaryCodec.Result.Ok).value
            assertEquals(vector.label(), vector.int("kept_entries"), decoded.entries.size)
        }
    }

    @Test
    fun `requests encode and decode as the vectors say`() {
        for (vector in section("request_valid")) {
            val want = vector.map("decoded")
            @Suppress("UNCHECKED_CAST")
            val categories = (want["categories"] as List<Number>).map { it.toInt() }
            val decoded = (BridgeSummaryCodec.decodeRequest(vector.frame()) as BridgeSummaryCodec.Result.Ok).value
            assertEquals(vector.label(), want.int("lat_e6"), decoded.latitudeE6)
            assertEquals(want.int("lon_e6"), decoded.longitudeE6)
            assertEquals(want.int("radius_km"), decoded.radiusKm)
            assertEquals((want["since_s"] as Number?)?.toLong(), decoded.sinceSeconds)
            assertEquals(categories, decoded.categories)
            // The request names the rounded point; encoding the decoded values gives the frame back,
            // with the radius as sent (0 means the default).
            val sentRadius = vector.frame()[5].toInt() and 0xFF
            val again = BridgeSummaryCodec.encodeRequest(decoded.latitudeE6, decoded.longitudeE6, sentRadius, decoded.sinceSeconds, categories)
            assertEquals(vector.label(), vector["frame"], hex(again))
        }
        for (vector in section("request_invalid")) {
            val result = BridgeSummaryCodec.decodeRequest(vector.frame())
            assertEquals(vector.label(), BridgeSummaryCodec.Result.Failed(BridgeSummaryCodec.Error.valueOf(vector["error"] as String)), result)
        }
    }

    @Test
    fun `the claim winner is the one the vectors name`() {
        for (vector in section("claims")) {
            val area = vector["area"] as String
            val claims = vector.list("claims").map { (it["pubkey"] as String) to it.int("hops") }
            assertEquals(vector.label(), vector.int("winner"), BridgeSummaryCodec.claimWinner(area, claims))
            @Suppress("UNCHECKED_CAST")
            val ranks = vector["ranks"] as List<String>
            for ((claim, rank) in claims.zip(ranks)) assertEquals(rank, hex(BridgeSummaryCodec.claimHash(claim.first, area)))
        }
    }

    @Test
    fun `airtime and packet sizes match the vectors`() {
        for (row in section("airtime")) {
            val size = BridgeSummaryCodec.packetBytes(row.int("content_bytes"), row["region"] == true)
            assertEquals(row.int("packet_bytes"), size)
            val ms = BridgeSummaryCodec.airtimeMillis(row.int("sf"), row.int("bw_hz"), row.int("cr"), size)
            assertEquals(row.toString(), (row["airtime_ms"] as Number).toDouble(), ms, 0.001)
        }
    }

    @Test
    fun `frame families are told apart by the first byte`() {
        assertEquals(BridgeSummaryCodec.Family.Signed, BridgeSummaryCodec.familyOf(byteArrayOf(0x08)))
        assertEquals(BridgeSummaryCodec.Family.Summary, BridgeSummaryCodec.familyOf(byteArrayOf(0x10)))
        assertEquals(BridgeSummaryCodec.Family.Request, BridgeSummaryCodec.familyOf(byteArrayOf(0x20)))
        assertEquals(BridgeSummaryCodec.Family.Unknown, BridgeSummaryCodec.familyOf(byteArrayOf(0x30)))
        // A version-0 decoder refuses both new frames instead of misreading them.
        val summary = unhex(section("summary_valid").first()["frame"] as String)
        assertEquals(CompactOutcome.Failed(CompactError.BAD_VERSION), CompactRoadCodec.decode(summary + ByteArray(130)))
    }

    private fun unhex(text: String): ByteArray = ByteArray(text.length / 2) { text.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

    private fun hex(bytes: ByteArray): String = bytes.joinToString("") { "%02x".format(it) }
}
